// Book highlights: the passages you highlighted in the ePub reader, one at a
// time and as big as the screen takes, with the book and your note under it;
// a new one every so often (the scene's interval), and the one you made last
// first. A tap, a swipe, the arrows or the frame's buttons go on to the next
// (or back); a long press (or the Action key, Enter) opens the book at it in
// the reader.
//
// The reader writes them to Highlights.json in its Notes folder whenever one
// changes; a Kindle's "My Clippings.txt" can be shown too (the clippings
// field). Nothing is written here but the scene's own place (spot).

import { HIGHLIGHTS_NAME, fromHighlights, fromClippings, merged, pick } from './quotes'

const LOOKS = {
  light: { bg: 'bg-[#f7f3ea]', ink: 'text-[#221c15]', muted: 'text-[#7a6e5f]', accent: 'text-[#b4532a]', rule: 'bg-[#b4532a]' },
  sepia: { bg: 'bg-[#efe1c4]', ink: 'text-[#3a2918]', muted: 'text-[#7b6247]', accent: 'text-[#9b3d1b]', rule: 'bg-[#9b3d1b]' },
  dark: { bg: 'bg-[#15171c]', ink: 'text-[#ede7db]', muted: 'text-[#9a9ea6]', accent: 'text-[#d9a35b]', rule: 'bg-[#d9a35b]' },
}

// Paper has inks and no greys worth the name: solid black and white, and the
// accent in red where the panel has it.
function lookOf(app) {
  const name = LOOKS[app.state.look] ? app.state.look : 'light'
  if (!app.frame.paper) return LOOKS[name]
  const red = app.frame.color !== false
  if (name === 'dark') return { bg: 'bg-black', ink: 'text-white', muted: 'text-white', accent: red ? 'text-[#ffd400]' : 'text-white', rule: red ? 'bg-[#ffd400]' : 'bg-white' }
  return { bg: 'bg-white', ink: 'text-black', muted: 'text-black', accent: red ? 'text-[#c00000]' : 'text-black', rule: red ? 'bg-[#c00000]' : 'bg-black' }
}

function readSpot(app) {
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch (e) {
      spot = null
    }
  }
  return spot && typeof spot === 'object' && !Array.isArray(spot) ? spot : {}
}

const saveSpot = (spot) => frameos.setState('spot', spot)

const folderOf = (app) => (typeof app.state.folder === 'string' ? app.state.folder.trim().replace(/^\/+|\/+$/g, '') : '') || 'Books'

// The quotes there are, and why there are none.
function quotesOf(app) {
  const notes = `${folderOf(app)}/Notes`
  const path = `${notes}/${HIGHLIGHTS_NAME}`
  let quotes = []
  if (frameos.assetExists(path)) quotes = fromHighlights(frameos.readAsset(path, { text: true }) || '')
  const clippings = typeof app.state.clippings === 'string' ? app.state.clippings.trim().replace(/^\/+/, '') : ''
  let missing = ''
  if (clippings) {
    if (!frameos.assetExists(clippings)) missing = clippings
    else {
      // The end of a long one: the newest clippings, as a Kindle adds them there.
      const size = frameos.assetSize(clippings)
      const most = app.frame.embedded ? 512 * 1024 : 4 * 1024 * 1024
      const offset = Math.max(0, size - most)
      const text = frameos.readAsset(clippings, { text: true, offset, length: size - offset }) || ''
      quotes = merged(quotes, fromClippings(text, offset > 0))
    }
  }
  const storages = app.frame.storages
  const noCard = Array.isArray(storages) && !storages.some((s) => s && s.id === 'assets')
  return { quotes, notes, missing, noCard }
}

const STEPS = { next: 1, prev: -1 }

export function onEvent(app, context) {
  const p = context.payload || {}
  const event = context.event
  let cmd = null
  if (event === 'tap') cmd = 'next'
  else if (event === 'longPress') cmd = 'open'
  else if (event === 'forward') cmd = 'next'
  else if (event === 'back') cmd = 'prev'
  else if (event === 'swipe') cmd = p.direction === 'left' || p.direction === 'up' ? 'next' : p.direction === 'right' || p.direction === 'down' ? 'prev' : null
  else if (event === 'keyDown') {
    if (p.ctrl || p.alt || p.meta) return false
    const key = p.key
    if (key === 'ArrowRight' || key === 'ArrowDown' || key === 'PageDown' || key === ' ') cmd = 'next'
    else if (key === 'ArrowLeft' || key === 'ArrowUp' || key === 'PageUp') cmd = 'prev'
    else if (key === 'Enter') cmd = 'open'
  } else if (event === 'button') {
    if (p.action !== 'press') return false
    const role = String(p.role || '').toLowerCase()
    const label = String(p.label || '').toUpperCase()
    if (role === 'next' || role === 'right' || role === 'down' || (!role && (label === 'DOWN' || label === 'RIGHT' || label === 'NEXT'))) cmd = 'next'
    else if (role === 'prev' || role === 'left' || role === 'up' || (!role && (label === 'UP' || label === 'LEFT' || label === 'PREV' || label === 'PREVIOUS'))) cmd = 'prev'
    else if (role === 'primary') cmd = 'open'
  }
  if (!cmd) return false
  const spot = readSpot(app)
  if (cmd === 'open') return openBook(app, spot)
  // Steps add up: taps that come while e-paper refreshes all count.
  spot.step = Math.max(-20, Math.min(20, (spot.step || 0) + STEPS[cmd]))
  saveSpot(spot)
  return true
}

// The book of the highlight showing, at it, in the scene that opens .epub
// files (the ePub reader): its file and mark fields. A Kindle clipping has no
// book on the frame.
function openBook(app, spot) {
  if (!spot.book) return false
  const reader = (app.frame.scenes || []).find((s) => s && String(s.opens || '').toLowerCase().split(/[\s,]+/).includes('epub'))
  if (!reader) {
    spot.notice = 'Install the ePub reader to open the book from here.'
    saveSpot(spot)
    return true
  }
  frameos.dispatch('setCurrentScene', { sceneId: reader.id, state: { file: spot.book, mark: spot.id } })
  return false
}

// The biggest text size at which the paragraphs fit height in width, found
// by halves; at the least size, how many lines fit when they do not.
function fitted(paras, font, width, height, least, most) {
  const lineOf = (size) => Math.round(size * 1.28)
  const gapOf = (size) => Math.round(size * 0.45)
  const classOf = (size) => `${font} text-[${size}px] leading-[${lineOf(size)}px]`
  const fits = (size) => {
    let total = gapOf(size) * (paras.length - 1)
    for (const h of frameos.measureText(paras, { className: classOf(size), width })) total += h
    return total <= height
  }
  const result = (size, lines) => ({ size, line: lineOf(size), gap: gapOf(size), lines })
  if (!fits(least)) return result(least, Math.max(1, Math.floor(height / lineOf(least))))
  let lo = least
  let hi = most
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1
    if (fits(mid)) lo = mid
    else hi = mid
  }
  return result(fits(hi) ? hi : lo, 0)
}

const PEN = 'M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04a1 1 0 0 0 0-1.41l-2.34-2.34a1 1 0 0 0-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z'

export function get(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const look = lookOf(app)
  const round = context.round === true
  const short = Math.min(W, H)
  const now = Date.now()

  // Where it goes: the square inside a round panel, else the panel less a margin.
  const margin = Math.round(short * 0.075)
  const side = round ? Math.floor((short / 2 - 12) * Math.SQRT2) : 0
  const box = round
    ? { x: (W - side) >> 1, y: (H - side) >> 1, w: side, h: side }
    : { x: Math.round(margin * 1.15), y: margin, w: W - Math.round(margin * 2.3), h: H - margin * 2 }

  // Which one: the next when its time is up or someone asked.
  const kept = readSpot(app)
  const { quotes, notes, missing, noCard } = quotesOf(app)
  const interval = Number(app.state.interval) > 0 ? Number(app.state.interval) : 3600
  const by = kept.step || 0
  const due = !kept.t || now - kept.t >= interval * 1000 - 1500
  const order = app.state.order === 'newest' || app.state.order === 'book' ? app.state.order : 'shuffle'
  let chosen = pick(quotes, kept, Math.sign(by), due, order, now)
  for (let k = 1; k < Math.min(Math.abs(by), quotes.length); k++) chosen = pick(quotes, chosen.spot, Math.sign(by), false, order, now)
  const quote = chosen.quote
  const notice = kept.notice
  const spot = { ...chosen.spot, book: quote ? quote.book : '' }
  delete spot.step
  delete spot.notice
  if (chosen.spot !== kept || by !== 0 || notice || spot.book !== kept.book) saveSpot(spot)
  // The next quote when its time is up, however this render came.
  if (quote && spot.t) {
    const left = interval - (now - spot.t) / 1000
    if (left > 1 && left < interval - 1) frameos.setNextSleep(left)
  }

  const hint = Math.max(13, Math.round(short / 34))
  if (!quote) {
    const why = noCard
      ? 'The ePub reader keeps its highlights on the TF card, and this frame has none in.'
      : 'Highlight a passage in the ePub reader and it shows here, one at a time.'
    return (
      <div className={`w-[${W}px] h-[${H}px] ${look.bg} flex items-center justify-center`}>
        <div className={`w-[${box.w}px] flex flex-col items-center text-center gap-[${hint}px]`}>
          <div className={`font-[Cormorant_Garamond] text-[${hint * 6}px] leading-[${hint * 4}px] ${look.accent}`}>“</div>
          <div className={`text-[${Math.round(hint * 1.8)}px] font-bold ${look.ink}`}>No highlights yet</div>
          <div className={`text-[${hint}px] leading-[${Math.round(hint * 1.4)}px] ${look.muted}`}>{why}</div>
          {missing ? <div className={`text-[${hint}px] ${look.muted}`}>{`No Kindle clippings at ${missing}.`}</div> : null}
          <div className={`text-[${Math.round(hint * 0.85)}px] ${look.muted}`}>{`Looking in ${notes}`}</div>
        </div>
      </div>
    )
  }

  // Under the quote: a short rule, the book, its author and chapter, the note.
  const small = Math.max(12, Math.round(Math.min(short / 27, box.w / 22)))
  const showNote = app.state.notes !== false && app.state.notes !== 'false' && quote.note
  const byline = [quote.author, quote.chapter].filter(Boolean).join(' · ')
  const noteWidth = box.w - Math.round(small * 1.6)
  const noteHeight = showNote ? Math.min(frameos.measureText([quote.note], { className: `italic text-[${small}px] leading-[${Math.round(small * 1.35)}px]`, width: noteWidth })[0], Math.round(small * 1.35) * 2) : 0
  const gap = Math.round(small * 1.4)
  const foot = gap + 3 + Math.round(small * 0.8) + Math.round(small * 1.45) + (byline ? Math.round(small * 1.3) : 0) + (showNote ? Math.round(small * 0.6) + noteHeight : 0) + (notice ? Math.round(small * 1.4) : 0)

  // The quote as big as the room left takes it.
  const typeface = typeof app.state.typeface === 'string' ? app.state.typeface : 'Cormorant Garamond'
  const font = typeface && typeface !== 'Ubuntu' ? `font-[${typeface.replace(/\s+/g, '_')}]` : ''
  // Its paragraphs, each a block (a UI's text folds its line breaks into
  // spaces). A short one is set centred, in quotation marks unless it opens
  // with its own (a line of dialogue); a long one reads better from the left.
  const centred = round || quote.text.length <= 160
  let paras = quote.text.split(/\n+/).map((t) => t.replace(/\s+/g, ' ').trim()).filter(Boolean)
  if (centred && !/^["“‘'«„‹(\[]/.test(paras[0])) {
    paras[0] = '“' + paras[0]
    paras[paras.length - 1] += '”'
  }
  const fit = fitted(paras, font, box.w, box.h - foot, Math.max(14, Math.round(short / 26)), Math.round(Math.min(box.h * 0.2, box.w / 7)))
  // Too long even at the least size: one paragraph, cut where the room ends.
  if (fit.lines) paras = [paras.join(' ')]
  const align = centred ? 'items-center text-center' : 'items-start text-left'
  // The opening mark, in the margin above the quote's first line.
  const markSize = Math.round(Math.min(fit.size * 2.2, margin * 2.4))

  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${look.bg}`}>
      {!round && !centred ? (
        <div className={`absolute left-[${Math.round(margin * 0.2)}px] top-[${Math.round(margin * 0.15)}px] font-[Cormorant_Garamond] text-[${markSize}px] leading-[${markSize}px] ${look.accent}`}>“</div>
      ) : null}
      <div className={`absolute left-[${box.x}px] top-[${box.y}px] w-[${box.w}px] h-[${box.h}px] flex flex-col justify-center ${align}`}>
        <div className={`w-full flex flex-col gap-[${fit.gap}px] ${align}`}>
          {paras.map((para) => (
            <div className={`${font} text-[${fit.size}px] leading-[${fit.line}px] ${look.ink} ${fit.lines ? `line-clamp-${fit.lines}` : ''}`}>{para}</div>
          ))}
        </div>
        <div className={`mt-[${gap}px] w-[${Math.round(small * 2.6)}px] h-[3px] ${look.rule}`} />
        <div className={`mt-[${Math.round(small * 0.8)}px] w-full text-[${Math.round(small * 1.15)}px] leading-[${Math.round(small * 1.45)}px] font-bold ${look.ink} truncate`}>{quote.title || 'Untitled'}</div>
        {byline ? <div className={`w-full text-[${small}px] leading-[${Math.round(small * 1.3)}px] ${look.muted} truncate`}>{byline}</div> : null}
        {showNote ? (
          <div className={`mt-[${Math.round(small * 0.6)}px] flex flex-row gap-[${Math.round(small * 0.5)}px] ${centred ? 'justify-center' : ''} w-full`}>
            <svg viewBox="0 0 24 24" className={`w-[${small}px] h-[${small}px] mt-[${Math.round(small * 0.2)}px] ${look.accent}`}>
              <path d={PEN} fill="currentColor" />
            </svg>
            <div className={`italic text-[${small}px] leading-[${Math.round(small * 1.35)}px] ${look.muted} line-clamp-2 max-w-[${noteWidth}px]`}>{quote.note}</div>
          </div>
        ) : null}
        {notice ? <div className={`mt-[${Math.round(small * 0.6)}px] text-[${small}px] ${look.muted}`}>{notice}</div> : null}
      </div>
    </div>
  )
}

