// What the Book highlights scene shows, and in which order.
//
// The ePub reader keeps every highlight in Highlights.json in its Notes
// folder (Books/Notes unless its books folder is another), and a Kindle (or
// any reader that exports one) keeps them in a "My Clippings.txt". Both are
// read into quotes: { id, book, title, author, chapter, text, note, at, pos },
// book being the reader's key for the book ('' for a clipping), at when it was
// made (ms, 0 when unknown) and pos where it is in its book.

export const HIGHLIGHTS_NAME = 'Highlights.json'

const str = (v) => (typeof v === 'string' ? v : '')

// FNV-1a, for ids and the shuffle: the same text gives the same number on every frame.
export function hash(text) {
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  return h >>> 0
}

// ---- The ePub reader's Highlights.json ------------------------------------------------

export function fromHighlights(text) {
  let data = null
  try {
    data = JSON.parse(text)
  } catch (e) {
    return []
  }
  if (!data || data.format !== 'frameos-highlights' || !Array.isArray(data.highlights)) return []
  const out = []
  for (const h of data.highlights) {
    if (!h || typeof h.text !== 'string' || !h.text.trim()) continue
    out.push({
      id: String(h.id || hash(str(h.title) + '|' + h.text)),
      book: str(h.book),
      title: str(h.title),
      author: str(h.author),
      chapter: str(h.chapter),
      text: h.text.trim(),
      note: str(h.note).trim(),
      at: Number(h.at) || 0,
      pos: Number(h.f) || 0,
    })
  }
  return out
}

// ---- A Kindle's "My Clippings.txt" ---------------------------------------------------

const MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']
const ADDED = /(\d{1,2})?\s*(january|february|march|april|may|june|july|august|september|october|november|december)\s*(\d{1,2})?,?\s+(\d{4})\D+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*([ap]m)?/i

// "Added on Monday, March 2, 2020 9:15:32 PM" (or the day first, as a UK
// Kindle writes it), in the frame's time; 0 for a Kindle in another language.
export function kindleTime(line) {
  const m = ADDED.exec(line)
  if (!m) return 0
  const day = Number(m[1] || m[3])
  if (!day) return 0
  let hour = Number(m[5]) % 24
  const half = (m[8] || '').toLowerCase()
  if (half === 'pm' && hour < 12) hour += 12
  if (half === 'am' && hour === 12) hour = 0
  return new Date(Number(m[4]), MONTHS.indexOf(m[2].toLowerCase()), day, hour, Number(m[6]), Number(m[7] || 0)).getTime()
}

// Its highlights, in the file's order. A highlight made longer is written
// again, so the newer of two that overlap in one book is kept; a note goes
// with the highlight of its book that it is at the end of; bookmarks (no text)
// are left out. A file read from its middle starts at its first whole one.
export function fromClippings(text, fromMiddle = false) {
  let body = text.replace(/\r/g, '').replace(/^﻿/, '')
  if (fromMiddle) {
    const first = body.indexOf('==========\n')
    body = first < 0 ? '' : body.slice(first + 11)
  }
  const out = []
  const notes = []
  for (const part of body.split(/\n?==========\n?/)) {
    const lines = part.split('\n')
    let i = 0
    while (i < lines.length && !lines[i].trim()) i++
    if (i + 1 >= lines.length) continue
    const head = lines[i].replace(/^﻿/, '').trim()
    const meta = lines[i + 1]
    const said = lines.slice(i + 2).join('\n').trim()
    if (!head || !said) continue
    const named = /^(.*\S)\s*\(([^()]*)\)$/.exec(head)
    const title = named ? named[1] : head
    const author = named ? named[2].trim() : ''
    const loc = /location\s+(\d+)(?:\s*-\s*(\d+))?/i.exec(meta)
    const from = loc ? Number(loc[1]) : -1
    const to = loc ? Number(loc[2] || loc[1]) : -1
    if (/\bnote\b/i.test(meta)) {
      notes.push({ title, at: to, text: said, index: out.length })
      continue
    }
    if (/\bbookmark\b/i.test(meta)) continue
    const quote = { id: 'k' + hash(title + '|' + said).toString(36), book: '', title, author, chapter: '', text: said, note: '', at: kindleTime(meta), pos: from, to }
    let replaced = false
    for (let j = out.length - 1; j >= 0 && j >= out.length - 10; j--) {
      const o = out[j]
      if (o.title === title && from >= 0 && o.pos >= 0 && from <= o.to && to >= o.pos && (said.includes(o.text) || o.text.includes(said))) {
        out[j] = quote
        replaced = true
        break
      }
    }
    if (!replaced) out.push(quote)
  }
  for (const n of notes) {
    let best = null
    for (let j = Math.max(0, n.index - 10); j < Math.min(out.length, n.index + 10); j++) {
      const o = out[j]
      if (o.title === n.title && n.at >= o.pos && n.at <= o.to + 1 && (!best || Math.abs(j - n.index) < Math.abs(best.j - n.index))) best = { j, o }
    }
    if (best) best.o.note = best.o.note ? best.o.note + '\n' + n.text : n.text
  }
  for (const o of out) delete o.to
  return out
}

// Both, the reader's first: a passage both have shows once.
export function merged(...lists) {
  const seen = new Set()
  const out = []
  const key = (q) => (q.title.toLowerCase() + '|' + q.text.replace(/\s+/g, ' ').slice(0, 80)).toLowerCase()
  for (const list of lists) {
    for (const q of list) {
      const k = key(q)
      if (seen.has(k)) continue
      seen.add(k)
      out.push(q)
    }
  }
  return out
}

// ---- The order ------------------------------------------------------------------------

function mix(x) {
  x = Math.imul(x ^ (x >>> 16), 0x45d9f3b)
  x = Math.imul(x ^ (x >>> 16), 0x45d9f3b)
  return (x ^ (x >>> 16)) >>> 0
}

// order: 'shuffle' (a new order every time round), 'newest' first, or 'book'
// (book by book, each in the order it reads).
export function deckOf(quotes, order, seed) {
  if (order === 'newest') return quotes.slice().sort((a, b) => b.at - a.at)
  if (order === 'book') return quotes.slice().sort((a, b) => (a.title < b.title ? -1 : a.title > b.title ? 1 : a.pos - b.pos))
  return quotes
    .map((q) => ({ k: mix(hash(q.id) ^ seed), q }))
    .sort((a, b) => a.k - b.k)
    .map((x) => x.q)
}

// Which quote shows. spot is what the scene keeps: the quote showing (id),
// the shuffle's seed and the quote its round started at (start), when it went
// up (t) and the newest highlight it has shown (seen). by is a step the person asked for (1, -1, 0), due whether the
// quote's time is up. A highlight made since (newer than seen) comes next,
// before the rest; the first time, the newest. Returns { quote, spot }, spot
// changed only when the quote did.
export function pick(quotes, spot, by, due, order, now) {
  if (quotes.length === 0) return { quote: null, spot }
  const next = { ...spot }
  if (typeof next.seed !== 'number') next.seed = (now % 2147483647) >>> 0
  const showing = quotes.find((q) => q.id === spot.id) || null
  const forward = by > 0 || (by === 0 && (due || !showing))
  let newest = 0
  for (const q of quotes) newest = Math.max(newest, q.at)
  if (forward && typeof spot.seen !== 'number') {
    const first = quotes.reduce((a, q) => (q.at > a.at ? q : a), quotes[0])
    return { quote: first, spot: { ...next, id: first.id, t: now, seen: newest, start: first.id } }
  }
  if (forward) {
    // The oldest of those made since the last one shown.
    let fresh = null
    for (const q of quotes) if (q.at > spot.seen && (!fresh || q.at < fresh.at)) fresh = q
    if (fresh) return { quote: fresh, spot: { ...next, id: fresh.id, t: now, seen: fresh.at } }
  }
  if (!forward && by === 0) return { quote: showing, spot }
  // Round the deck from the one showing. A round of a shuffle ends when it
  // comes back to where it started (start): every one has shown, and the next
  // round goes in a new order, not starting with the one that just showed.
  let deck = deckOf(quotes, order, next.seed)
  const n = deck.length
  const at = showing ? deck.findIndex((q) => q.id === showing.id) : -1
  let i = at < 0 ? (by < 0 ? n - 1 : 0) : (at + (by < 0 ? -1 : 1) + n) % n
  const shuffled = order !== 'newest' && order !== 'book'
  if (shuffled && by >= 0 && deck[i].id === next.start) {
    next.seed = mix(next.seed + 1)
    deck = deckOf(quotes, order, next.seed)
    i = n > 1 && deck[0].id === spot.id ? 1 : 0
    next.start = deck[i].id
  }
  if (!quotes.some((q) => q.id === next.start)) next.start = deck[i].id
  const quote = deck[i]
  return { quote, spot: { ...next, id: quote.id, t: now } }
}

