import { fromHighlights, fromClippings, kindleTime, merged, deckOf, pick } from './quotes'

const reader = (highlights) => JSON.stringify({ format: 'frameos-highlights', version: 1, highlights })

const q = (id, at, title = 'A Book', pos = 0) => ({ id, book: '', title, author: '', chapter: '', text: `Text ${id}`, note: '', at, pos })

describe("the ePub reader's Highlights.json", () => {
  it('reads its highlights, and nothing from what is not one', () => {
    const quotes = fromHighlights(
      reader([
        { id: 'h1', book: 'assets:Books/Emma.epub', title: 'Emma', author: 'Jane Austen', chapter: 'Volume I', text: ' One line.\nAnother. ', note: 'Mine', at: 5, f: 0.25 },
        { id: 'h2', title: 'Emma', text: '   ' },
        null,
      ]),
    )
    expect(quotes).toEqual([{ id: 'h1', book: 'assets:Books/Emma.epub', title: 'Emma', author: 'Jane Austen', chapter: 'Volume I', text: 'One line.\nAnother.', note: 'Mine', at: 5, pos: 0.25 }])
    expect(fromHighlights('{"format":"frameos-books","marks":{}}')).toEqual([])
    expect(fromHighlights('not json')).toEqual([])
  })
})

describe("a Kindle's My Clippings.txt", () => {
  const clippings = [
    '﻿The Old Man and the Sea (Ernest Hemingway)',
    '- Your Highlight on page 103 | Location 1569-1570 | Added on Monday, March 2, 2020 9:15:32 PM',
    '',
    'A man can be destroyed',
    '==========',
    'The Old Man and the Sea (Ernest Hemingway)',
    '- Your Highlight on page 103 | Location 1569-1571 | Added on Monday, March 2, 2020 9:16:01 PM',
    '',
    'A man can be destroyed but not defeated.',
    '==========',
    'The Old Man and the Sea (Ernest Hemingway)',
    '- Your Note on page 103 | Location 1571 | Added on Monday, March 2, 2020 9:16:40 PM',
    '',
    'Read this again.',
    '==========',
    'Walden (Thoreau, Henry David)',
    '- Your Bookmark on page 4 | Location 52 | Added on Tuesday, 3 March 2020 07:01:00',
    '',
    '',
    '==========',
    'Walden (Thoreau, Henry David)',
    '- Your Highlight at location 88-90 | Added on Tuesday, 3 March 2020 07:02:00',
    '',
    'I went to the woods because I wished to live deliberately.',
    '==========',
    '',
  ].join('\r\n')

  it('reads highlights with their books and authors, a longer one in place of the one it grew from, a note with its highlight, no bookmarks', () => {
    const quotes = fromClippings(clippings)
    expect(quotes.length).toBe(2)
    expect(quotes[0]).toMatchObject({ title: 'The Old Man and the Sea', author: 'Ernest Hemingway', text: 'A man can be destroyed but not defeated.', note: 'Read this again.', book: '', pos: 1569 })
    expect(quotes[1]).toMatchObject({ title: 'Walden', author: 'Thoreau, Henry David', text: 'I went to the woods because I wished to live deliberately.', note: '' })
    expect(quotes[0].id).toMatch(/^k/)
    expect(quotes[0].id).not.toBe(quotes[1].id)
  })

  it('reads when each was added, either way round, and 0 in another language', () => {
    expect(kindleTime('- Your Highlight | Added on Monday, March 2, 2020 9:15:32 PM')).toBe(new Date(2020, 2, 2, 21, 15, 32).getTime())
    expect(kindleTime('- Your Highlight | Added on Tuesday, 3 March 2020 07:02:00')).toBe(new Date(2020, 2, 3, 7, 2, 0).getTime())
    expect(kindleTime('- Your Highlight | Added on Monday, March 2, 2020 12:05:00 AM')).toBe(new Date(2020, 2, 2, 0, 5, 0).getTime())
    expect(kindleTime('- Votre surlignement | Ajouté le lundi 2 mars 2020 21:15:32')).toBe(0)
  })

  it('read from its middle, starts at the first whole clipping', () => {
    const tail = clippings.slice(clippings.indexOf('Location 1569-1571') - 10)
    const quotes = fromClippings(tail, true)
    expect(quotes.map((x) => x.title)).toEqual(['Walden'])
  })

  it('a passage both the reader and a clippings file have shows once, as the reader has it', () => {
    const a = { ...q('h1', 1, 'Walden'), text: 'I went to the woods because I wished to live deliberately.', book: 'assets:Books/Walden.epub' }
    const all = merged([a], fromClippings(clippings))
    expect(all.length).toBe(2)
    expect(all[0].book).toBe('assets:Books/Walden.epub')
  })
})

describe('the order', () => {
  const quotes = [q('a', 10, 'B', 2), q('b', 30, 'A', 9), q('c', 20, 'A', 1), q('d', 40, 'B', 1)]

  it('newest first, book by book in reading order, or shuffled the same way for a seed', () => {
    expect(deckOf(quotes, 'newest', 1).map((x) => x.id)).toEqual(['d', 'b', 'c', 'a'])
    expect(deckOf(quotes, 'book', 1).map((x) => x.id)).toEqual(['c', 'b', 'd', 'a'])
    const one = deckOf(quotes, 'shuffle', 7).map((x) => x.id)
    expect(deckOf(quotes, 'shuffle', 7).map((x) => x.id)).toEqual(one)
    expect(one.slice().sort()).toEqual(['a', 'b', 'c', 'd'])
  })

  it('starts with the newest, stays until its time is up, then shows every one before any again', () => {
    let { quote, spot } = pick(quotes, {}, 0, true, 'shuffle', 1000)
    expect(quote.id).toBe('d')
    expect(spot).toMatchObject({ id: 'd', t: 1000, seen: 40, start: 'd' })
    const stay = pick(quotes, spot, 0, false, 'shuffle', 2000)
    expect(stay.quote.id).toBe('d')
    expect(stay.spot).toBe(spot)
    const shown = [quote.id]
    for (let i = 0; i < 3; i++) {
      ;({ quote, spot } = pick(quotes, spot, 0, true, 'shuffle', 3000 + i))
      shown.push(quote.id)
    }
    expect(shown.slice().sort()).toEqual(['a', 'b', 'c', 'd'])
    // Round again, in a new order, not the one that just showed first.
    const again = pick(quotes, spot, 1, false, 'shuffle', 9000)
    expect(again.quote.id).not.toBe(quote.id)
    expect(again.spot.seed).not.toBe(spot.seed)
  })

  it('back goes the other way through the same order', () => {
    const first = pick(quotes, { id: 'b', seed: 3, seen: 40, t: 1 }, 1, false, 'newest', 5)
    expect(first.quote.id).toBe('c')
    expect(pick(quotes, first.spot, -1, false, 'newest', 6).quote.id).toBe('b')
    expect(pick(quotes, { id: 'd', seed: 3, seen: 40, t: 1 }, -1, false, 'newest', 6).quote.id).toBe('a')
  })

  it('a highlight made since comes next, before the rest', () => {
    const more = quotes.concat([q('e', 50), q('f', 60)])
    const spot = { id: 'a', seed: 3, seen: 40, t: 1 }
    const next = pick(more, spot, 0, true, 'shuffle', 100)
    expect(next.quote.id).toBe('e')
    expect(pick(more, next.spot, 1, false, 'shuffle', 101).quote.id).toBe('f')
  })

  it('one that was taken away gives way to another at once', () => {
    const left = pick(quotes, { id: 'gone', seed: 3, seen: 40, t: 1 }, 0, false, 'newest', 5)
    expect(left.quote).not.toBe(null)
    expect(pick([], {}, 0, true, 'shuffle', 5).quote).toBe(null)
  })
})
